INSERT INTO public.counter_effort_candidates VALUES ('696cfd7d-908d-41c0-a202-ea4e6fc23f50', NULL, '819e2ab2-67bb-4527-ac52-4389a065918b', 'EPA Coral Reef Protection Activities', 'Implements Clean Water Act programs to reduce land-based sources of pollution that degrade coastal waters and coral reefs, enhancing their natural resilience through regulatory and non-regulatory measures.', 'operating', 'https://globalfundcoralreefs.org/reef-plus/news/breakthrough-scaling-solutions-for-coral-reefs', 'globalfundcoralreefs.org', 'EPA protects coral reefs by implementing Clean Water Act programs that protect water quality in watersheds and coastal zones of coral reef areas.', 0.6, 0.6, true, '2026-07-27 12:32:21.582021+00');
INSERT INTO public.counter_effort_candidates VALUES ('4c015ab6-afdf-4b34-acf9-d1a3f07c8103', NULL, '819e2ab2-67bb-4527-ac52-4389a065918b', 'Coral Reef Stewardship Fund', 'A grant program managed by the National Fish and Wildlife Foundation that since 2000 has awarded $25 million across 426 projects to reduce threats to coral reefs, promote active restoration, and advance coral science.', 'operating', 'https://www.facebook.com/bloombergdotorg/posts/losing-coral-reefs-would-endanger-the-livelihoods-culture-food-security-and-heal/1247961335279839/', 'facebook.com', 'NFWF manages the Coral Reef Stewardship Fund in partnership with NOAA’s Coral Reef Conservation Program and Aramco.', 0.2, 0.05, false, '2026-07-27 12:32:27.308609+00');
INSERT INTO public.counter_effort_candidates VALUES ('ce3451c6-9a7f-4af8-8490-5ad01d481ee5', NULL, '5aa7bb62-3c21-45f0-93a5-99ceeeb4032e', 'Arête Glacier Initiative', 'Arête Glacier Initiative aims to measure and mitigate the risks of catastrophic sea-level rise through sea-level rise forecasting and glacier stabilization research.', 'research', 'https://arc.renaissancephilanthropy.org/', 'arc.renaissancephilanthropy.org', 'Arête Glacier Initiative aims to measure and mitigate the risks of catastrophic sea-level rise.', 0.6, 0.75, true, '2026-07-27 12:32:59.365892+00');
INSERT INTO public.counter_effort_candidates VALUES ('e0e6897d-a3ce-4a37-810f-55ccebe0db4b', NULL, 'a7703fe6-1a3f-4f25-bbfd-0e29483e5255', 'Saving Today’s at Risk Species', 'A program that partners with conservation efforts to apply genetic rescue to critically endangered species, aiming to bring back species on the brink of extinction.', 'operating', 'https://colossalfoundation.org/', 'colossalfoundation.org', 'Saving Today’s at Risk Species', 0.55, 0.05, false, '2026-07-27 12:33:41.258211+00');
INSERT INTO public.counter_effort_candidates VALUES ('5c9d0f93-6922-476d-a93c-5de13dec8f3d', NULL, 'a7703fe6-1a3f-4f25-bbfd-0e29483e5255', 'Engineering a Future for the Northern White Rhino', 'A project sequencing viable museum samples to restore genetic diversity and developing gene editing tools to enhance cell lines for embryo transfer, aimed at restoring the northern white rhino population.', 'research', 'https://colossalfoundation.org/', 'colossalfoundation.org', 'Engineering a Future for the Northern White Rhino', 0.75, 0.5, false, '2026-07-27 12:33:45.073775+00');
INSERT INTO public.counter_effort_candidates VALUES ('72d7d5a8-e2aa-4b8d-ac54-f1eb55389fdd', NULL, 'a7703fe6-1a3f-4f25-bbfd-0e29483e5255', 'Protecting Sumatran Rhinos from Extinction', 'A collaboration to enhance existing breeding programs and leverage genetic sequencing and assisted reproductive technologies to support and increase the population of Sumatran rhinos in Indonesia.', 'operating', 'https://colossalfoundation.org/', 'colossalfoundation.org', 'Protecting Sumatran Rhinos from Extinction', 0.5, 0.1, false, '2026-07-27 12:33:48.860278+00');
INSERT INTO public.counter_effort_candidates VALUES ('a5d36fb9-75b5-438f-b28e-4c039125ce1b', NULL, 'b1d28728-1171-4bc7-b779-cb5b5c18663f', 'The Nature Conservancy', 'Manages over 119 million acres of protected land and invests in habitat protection projects across the United States, focusing on climate-resilient landscapes and species corridor development.', 'operating', 'https://rare.org/stories-articles/best-nature-conservation-charities-and-organizations/', 'rare.org', 'The Nature Conservancy stands as America’s largest environmental organization by assets, managing over 119 million acres of protected land and 5,000 miles of rivers worldwide.', 0.75, 0.7, true, '2026-07-27 12:34:05.686694+00');
INSERT INTO public.counter_effort_candidates VALUES ('e2ca6d16-24a7-4532-918d-d02148fc4bdf', NULL, 'b1d28728-1171-4bc7-b779-cb5b5c18663f', 'WWF', 'Fights for wildlife conservation globally, protecting endangered animals on land, in rivers and in oceans through science-based conservation and partnerships.', 'operating', 'https://www.curlewcall.org/top-wildlife-conservation-organizations-in-the-us-2025/', 'curlewcall.org', 'The WWF is the world’s leading animal conservation charity.', 0.25, 0.65, false, '2026-07-27 12:34:10.818888+00');
INSERT INTO public.counter_effort_candidates VALUES ('016177c2-4e0b-429f-92af-737155704696', NULL, 'f6605a54-2bf5-44e2-a957-7dbe2220bc11', 'Biodiversity Finance Initiative (BIOFIN)', 'Helps countries unlock financing for nature, including innovative finance solutions to address land degradation, biodiversity loss, and climate change.', 'operating', 'https://www.fao.org/newsroom/detail/fao-report--1.7-billion-people-experience-lower-crop-yields-due-to-land-degradation/en?trk=public_post_comment-text', 'fao.org', 'Since 2018, UNDP’s Biodiversity Finance Initiative (BIOFIN) has helped 41 countries unlock over US $1Bn in financing for nature, with innovative finance solutions that span everything from crowdfunding to green bonds.', 0.95, 0.05, false, '2026-07-27 12:35:01.926608+00');
INSERT INTO public.counter_effort_candidates VALUES ('36d5a4dd-84e7-4bf2-94e6-b32fd12ea267', NULL, 'f6605a54-2bf5-44e2-a957-7dbe2220bc11', 'Regenerative Fund for Nature', 'Supports regenerative agricultural practices in the fashion industry''s supply chains to reduce environmental impact, restore soil health, and help local communities.', 'operating', 'https://www.biofin.org/news-and-media/these-innovative-finance-solutions-combat-land-degradation-climate-change-and', 'biofin.org', 'The Regenerative Fund for Nature. The fund supports innovative approaches to agricultural production by working with nature, not against it — starting with the fashion industry — to reduce the environmental impact of agriculture while helping local communities thrive.', 0.8, 0.3, false, '2026-07-27 12:35:05.924861+00');
INSERT INTO public.counter_effort_candidates VALUES ('b9d03bc1-6edb-453f-86ac-701f7a48cfaa', NULL, 'f6605a54-2bf5-44e2-a957-7dbe2220bc11', 'South Africa''s Biodiversity Stewardship Programme (BSP)', 'Forms agreements with private and communal landholders to protect and manage land in areas of significant biodiversity value, expanding protected areas and integrating conservation with land-use practices.', 'operating', 'https://www.fao.org/newsroom/detail/fao-report--1.7-billion-people-experience-lower-crop-yields-due-to-land-degradation/en?trk=public_post_comment-text', 'fao.org', 'South Africa''s Biodiversity Stewardship Programme (BSP) has been a key policy instrument for significantly increasing South Africa''s protected area coverage... BSP works by forming agreements with private and communal landholders to protect and manage land in areas of significant biodiversity value.', 0.95, 0.1, false, '2026-07-27 12:35:13.182456+00');
INSERT INTO public.counter_effort_candidates VALUES ('2ae77f7a-f5c4-484d-aae4-68f581ef24c6', NULL, 'f6605a54-2bf5-44e2-a957-7dbe2220bc11', 'Mongolia''s Natural Resource Use Fee Law (NRUF Law)', 'Taxes commercial use of natural resources such as land, with revenues increasingly directed to environmental expenditure, helping combat land degradation and biodiversity loss.', 'operating', 'https://www.fao.org/newsroom/detail/fao-report--1.7-billion-people-experience-lower-crop-yields-due-to-land-degradation/en?trk=public_post_comment-text', 'fao.org', 'With technical assistance from UNDP-BIOFIN the government made changes to its Natural Resource Use Fee Law (NRUF Law). In 2023, the Mongolia spent US$ 11.92 million from these fees on environmental expenditure, nearly double of earlier averages.', 0.95, 0.05, false, '2026-07-27 12:35:20.88789+00');
INSERT INTO public.counter_effort_candidates VALUES ('bb36feaa-b4e9-4fd7-b29c-71015c49c798', NULL, '977aaf44-df18-438d-922b-5ae6f982920f', 'Methane Emissions Reduction Program (MERP)', 'Provides $1.36 billion in financial and technical assistance, imposes a Waste Emissions Charge, and improves emissions reporting to reduce methane from the oil and gas sector.', 'operating', 'https://www.bloomberg.org/press/michael-r-bloomberg-launches-unprecedented-end-to-end-global-methane-emissions-reduction-effort-from-space-detection-to-rapid-response/', 'bloomberg.org', 'The Inflation Reduction Act provides new authorities under Section 136 of the Clean Air Act to reduce methane emissions from the petroleum and natural gas sector through the creation of the Methane Emissions Reduction Program.', 0.75, 0.65, true, '2026-07-27 12:36:25.168974+00');
INSERT INTO public.counter_effort_candidates VALUES ('ee012590-3c88-4bf7-96bc-c9a26ec823f2', NULL, '977aaf44-df18-438d-922b-5ae6f982920f', 'International Methane Emissions Observatory (IMEO)', 'Delivers training and technical guidance to governments and companies to reduce methane emissions from the oil and gas sector, and conducts scientific studies.', 'operating', 'https://www.epa.gov/inflation-reduction-act/methane-emissions-reduction-program', 'epa.gov', 'UNEP’s International Methane Emissions Observatory (IMEO), which delivers training and technical guidance to governments and companies looking to reduce methane emissions from the oil and gas sector.', 0.95, 0.7, true, '2026-07-27 12:36:31.620246+00');
INSERT INTO public.counter_effort_candidates VALUES ('d9e73180-1e0f-4652-a696-e0b15b5bd345', NULL, '977aaf44-df18-438d-922b-5ae6f982920f', 'WasteMAP', 'Launches a platform that integrates modeled and measured data and a partner network of satellite and sensor operators to make methane emissions from the oil and gas and waste sectors visible in near real-time.', 'deploying', 'https://www.youtube.com/watch?v=YFx96pG7ubo', 'youtube.com', 'Launching WasteMAP, a platform that integrates modeled and measured data and a partner network of satellite and sensor operators to make methane emissions from the oil and gas and waste sectors visible in near real-time.', 0.1, 0.7, false, '2026-07-27 12:36:39.103858+00');
INSERT INTO public.counter_effort_candidates VALUES ('fb51ea1e-fa92-4a58-a51d-7021a00f6721', NULL, '6fd4a628-78e6-486f-83a3-b070d0dc808e', 'Women''s Peace and Humanitarian Fund', 'Provides flexible and fast financing for integrated interventions that increase women''s participation in crisis response, conflict prevention, and peacebuilding, including supporting women activists in peace processes, negotiations, and implementation of peace agreements.', 'operating', 'https://www.wilpf.org/invest-in-peace/', 'wilpf.org', 'The Women''s Peace and Humanitarian Fund provides flexible and fast financing for integrated interventions that increase women’s participation in response to crises and emergencies, as well as preventing conflict, encouraging national ownership of development investments, and upholding peacebuilding commitments.', 0.8, 0.55, true, '2026-07-27 12:38:07.027115+00');
INSERT INTO public.counter_effort_candidates VALUES ('7b0955c2-5fc0-4d9f-944d-bfd08652a3c6', NULL, '6fd4a628-78e6-486f-83a3-b070d0dc808e', 'Women''s International League for Peace and Freedom (WILPF)', 'Works globally and locally to disarm violence, center gender justice, and build lasting peace; partners with over 30 organizations to advance feminist peace activism and reimagine inclusive peace and political processes in conflict-affected countries such as Libya, Iraq, Syria, Afghanistan, and Ukraine.', 'operating', 'https://www.humanrightscareers.com/magazine/organizations-gender-equality/', 'humanrightscareers.com', 'WILPF partners with more than 30 organisations to advance feminist peace activism and reimagine feminist alternatives to militarised and exclusive peace and political processes in Libya, Iraq, Syria, Afghanistan, Ukraine, and beyond.', 0.6, 0.7, true, '2026-07-27 12:38:11.926256+00');
INSERT INTO public.counter_effort_candidates VALUES ('c8d297aa-73dc-4b3b-874c-3710d4871b93', NULL, 'f749fdcd-1c98-405b-a638-4dca94cba555', 'Delaware River Port Authority (DRPA)', 'Making major capital investments in critical infrastructure improvements while maintaining financial stewardship and no toll increase, thereby addressing chronic underinvestment.', 'operating', 'https://greatergood.org/blog/the-impact-of-federal-funding-cuts-on-land-conservation?hs_amp=true', 'greatergood.org', 'Major capital investments. Strong financial stewardship. No toll increase. That disciplined approach, continued in 2025, delivered critical infrastructure improvements and...', 0.5, 0.7, true, '2026-07-27 12:38:32.554566+00');
INSERT INTO public.counter_effort_candidates VALUES ('54642a25-fc60-4125-bfbb-ebbf34c64231', NULL, '721779e7-4c0f-4b27-95ea-e741e5872fc1', 'World Nuclear Association', 'Works with partners worldwide to encourage political alignment around the need to rapidly scale nuclear energy through the Net Zero Nuclear initiative.', 'operating', 'https://world-nuclear.org/news-and-media/press-statements/four-more-countries-endorse-global-declaration-to-triple-nuclear-energy', 'world-nuclear.org', 'World Nuclear Association has worked with partners worldwide to encourage political alignment around the need to rapidly scale nuclear energy through the Net Zero Nuclear (NZN) initiative.', 0.6, 0.6, true, '2026-07-27 12:39:17.464248+00');
INSERT INTO public.counter_effort_candidates VALUES ('8b823a93-b729-450b-987e-b003b736758f', NULL, '721779e7-4c0f-4b27-95ea-e741e5872fc1', 'Net Zero Nuclear initiative', 'A WNA-led initiative that rallies industry and government support for the goal of tripling global nuclear capacity by 2050.', 'operating', 'https://world-nuclear.org/news-and-media/press-statements/four-more-countries-endorse-global-declaration-to-triple-nuclear-energy', 'world-nuclear.org', 'World Nuclear Association has worked with partners worldwide to encourage political alignment around the need to rapidly scale nuclear energy through the Net Zero Nuclear (NZN) initiative.', 0.85, 0.6, true, '2026-07-27 12:39:21.109738+00');
INSERT INTO public.counter_effort_candidates VALUES ('35ee994a-9f1f-4c78-aaea-b3e5b9d80f91', NULL, '721779e7-4c0f-4b27-95ea-e741e5872fc1', 'French Nuclear Strategic Committee (CSFN)', 'Co-hosted a round table with the World Nuclear Association to call for coordinated action to provide certainty and scale up delivery of nuclear energy.', 'operating', 'https://world-nuclear.org/news-and-media/press-statements/four-more-countries-endorse-global-declaration-to-triple-nuclear-energy', 'world-nuclear.org', 'World Nuclear Association and the French Nuclear Strategic Committee (CSFN) co-hosted a round table "One ambition for nuclear: Tripling Nuclear Energy".', 0.7, 0.4, false, '2026-07-27 12:39:29.298588+00');
INSERT INTO public.counter_effort_candidates VALUES ('fddc4f23-566e-457a-b27c-38a9e9ca8043', NULL, '721779e7-4c0f-4b27-95ea-e741e5872fc1', 'International Atomic Energy Agency (IAEA)', 'Released the Outlook for Nuclear Energy in Africa and co-organized the first high-level G20 meeting on nuclear energy to support deployment and tripling of nuclear capacity.', 'operating', 'https://www.iaea.org/newscenter/news/two-more-countries-join-global-pledge-to-triple-nuclear-energy-by-2050', 'iaea.org', 'IAEA also released the Outlook for Nuclear Energy in Africa as part of its collaboration with the South African G20 presidency.', 0.95, 0.1, false, '2026-07-27 12:39:38.640129+00');
INSERT INTO public.counter_effort_candidates VALUES ('c308ba89-c04a-4c67-860f-3c720ef1319c', NULL, '4b7f809d-92d1-4b22-a52e-690e23279086', 'SCALED Development', 'SCALED Development is an investment service firm designed to mobilize billions in private capital for sustainable development in emerging markets and developing economies, helping to close the financing gap and accelerate economic convergence.', 'operating', 'https://scaledevelopment.org/', 'scaledevelopment.org', 'Governments and several of the world’s leading institutional investors today launched SCALED Development, a new investment service firm designed to mobilize billions in private capital for sustainable development in emerging markets and developing economies.', 0.6, 0.5, false, '2026-07-27 12:40:49.789467+00');
INSERT INTO public.counter_effort_candidates VALUES ('b18aae55-d221-4660-bf52-2a621c212bb1', NULL, '4b7f809d-92d1-4b22-a52e-690e23279086', 'Action Plan to Increase Private Investment Mobilization', 'A coalition of governments, international organizations, and private sector groups is developing an Action Plan to deploy blended finance to mobilize private investment in underserved markets, with a dedicated track for Least Developed Countries and Africa, aiming to reduce the financing gap and support poverty reduction.', 'research', 'https://www.uncdf.org/article/8934/action-plan-to-increase-private-investment-mobilization', 'uncdf.org', 'A coalition of governments, international development partners and private sector groups including the UN Capital Development Fund, UN Economic Commission for Africa (ECA), Organisation for Economic Cooperation and Development (OECD), African Union Commission, Global Investors for Sustainable Development (GISD) Alliance, Ministry for Foreign Affairs of Finland, Norway Ministry of Foreign Affairs (MFA) and Norad, Switzerland SECO and Convergence Blended Finance, are announcing the development of an Action Plan to increase mobilize private sector capital at scale in developing countries.', 0.9, 0.6, true, '2026-07-27 12:40:54.278659+00');
INSERT INTO public.counter_effort_candidates VALUES ('09fcdb4c-252c-4586-9b53-0773d4f34cb1', '39d2b28f-ed0f-41f1-a5c2-e8be3516f607', NULL, 'Coral Reef Stewardship Fund', 'Promotes active coral restoration by building capacity for propagation and out-planting nursery-grown corals, and advances coral science through testing and refinement of best management practices.', 'operating', 'https://www.nfwf.org/programs/coral-reef-stewardship-fund', 'nfwf.org', 'NFWF manages the Coral Reef Stewardship Fund in partnership with NOAA’s Coral Reef Conservation Program and Aramco', 0.8, 0.5, false, '2026-07-27 13:25:53.274618+00');
INSERT INTO public.counter_effort_candidates VALUES ('58ef2190-9571-44a2-ae36-e2cb0f43a675', '39d2b28f-ed0f-41f1-a5c2-e8be3516f607', NULL, 'Global Fund for Coral Reefs', 'An innovative blended finance mechanism that deploys grant financing to build a pipeline of revenue-generating initiatives leveraging private investment for coral reef conservation, restoration, and adaptation technologies.', 'active', 'https://mptf.undp.org/fund/fcr00', 'mptf.undp.org', 'The Global Fund for Coral Reefs (GFCR) is an innovative blended finance mechanism stakeholders hope to use to mobilize $500 million US dollars in grants and investment capital to put towards coral reef ecosystem conservation and resilience', 0.95, 0.55, true, '2026-07-27 13:26:02.921378+00');
INSERT INTO public.counter_effort_candidates VALUES ('79bb0bac-17d0-4031-98dc-c87e996c7b88', '0a1ea0c3-5c2b-4359-942a-c64345f787cf', NULL, 'Coral Reef Breakthrough', 'A global initiative aiming to secure the future of at least 125,000 km² of shallow-water tropical coral reefs with investments of at least US$12 billion by 2030, through stopping local drivers of loss, doubling protected area, accelerating restoration, and mobilizing finance.', 'deploying', 'https://icriforum.org/g20-open-letter-for-coral-reefs/', 'icriforum.org', 'The Coral Reef Breakthrough aims to secure the future of at least 125,000 km2 of shallow-water tropical coral reefs with investments of at least US$12 billion to support the resilience of more than half a billion people globally by 2030.', 0.8, 0.95, true, '2026-07-27 13:28:42.543808+00');
INSERT INTO public.counter_effort_candidates VALUES ('02b09d55-353e-4472-8f38-54b834100064', '0a1ea0c3-5c2b-4359-942a-c64345f787cf', NULL, 'Global Fund for Coral Reefs (GFCR)', 'A blended finance vehicle that uses grants and investment capital to scale reef-positive businesses and conservation interventions, such as sustainable fisheries, ecotourism, and wastewater treatment, to address local drivers of coral reef degradation.', 'operating', 'https://icriforum.org/g20-open-letter-for-coral-reefs/', 'icriforum.org', 'The Global Fund for Coral Reefs (GFCR) is the first and only blended finance vehicle dedicated to coral reefs globally.', 0.85, 0.6, true, '2026-07-27 13:28:47.3276+00');
INSERT INTO public.counter_effort_candidates VALUES ('e8907edd-940b-4b96-a0ce-aee1d0460d80', '0a1ea0c3-5c2b-4359-942a-c64345f787cf', NULL, 'Coral Reef Stewardship Fund', 'A competitive grant program managed by NFWF in partnership with NOAA that funds U.S. coral reef conservation projects focused on threat reduction, active coral restoration, and advancing coral science and restoration capacity.', 'operating', 'https://coralvita.co/coral-cafe/corporate-funding-for-reef-restoration/', 'coralvita.co', 'NFWF manages the Coral Reef Stewardship Fund in partnership with NOAA’s Coral Reef Conservation Program and Aramco.', 0.3, 0.2, false, '2026-07-27 13:28:55.663672+00');
INSERT INTO public.counter_effort_candidates VALUES ('acbc3a2f-847f-489a-8e9e-d10c3bcf0e6b', NULL, 'a7703fe6-1a3f-4f25-bbfd-0e29483e5255', 'Re:wild', 'Protects and restores wildlife and ecosystems globally, with active conservation on over 590 million acres and direct conservation of 276 threatened species.', 'operating', 'https://www.rewild.org/', 'rewild.org', 'Re:wild protects and restores the wild.', 0.75, 0.3, false, '2026-07-27 13:32:01.096106+00');
INSERT INTO public.counter_effort_candidates VALUES ('b519943f-b2f4-4d5a-a785-0680a5538c5d', NULL, 'a7703fe6-1a3f-4f25-bbfd-0e29483e5255', 'Colossal', 'Uses genetic technologies to reintroduce endangered and extinct species to their natural habitats, aiming to restore biodiversity and reverse population declines.', 'unclear', 'https://colossal.com/conservation/', 'colossal.com', 'At Colossal, we''re not just committed to safeguarding the future. We''re committed to reintroducing species—both endangered and extinct—to the natural habitats that need them.', 0.6, 0.6, true, '2026-07-27 13:32:11.121156+00');
