INSERT INTO public.organisation_links VALUES ('466e87bf-0340-47e1-8543-7e062930e7be', 'a60ec0a9-af33-4248-9b87-8762a8cf534c', '9c55c293-3283-4926-a0e4-b8175f9ed182', NULL, 'addresses', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9511941/', 'pmc.ncbi.nlm.nih.gov', 'Founded in 1974 by the World Health Assembly, EPI''s original goal was to vaccinate all children against diphtheria, measles, pertussis, polio, tetanus, tuberculosis, as well as smallpox, the only human disease ever eradicated.', '2026-07-27 04:35:50.938179+00');
