INSERT INTO public.organisation_links VALUES ('8fb0e2a0-2008-4838-a525-992981c51af7', '901bebb7-65c9-4784-93cd-1a2968c54238', NULL, '67f93ce8-ccf3-4ccf-a48f-7dcf4524adc8', 'addresses', 'https://www.decadeonrestoration.org/publications/mapping-global-funding-landscape-coral-reef-restoration-international-coral-reef', 'decadeonrestoration.org', 'The National Fish and Wildlife Foundation (NFWF) will award grants to improve the health of coral reef systems.', '2026-07-27 04:39:27.666386+00');
INSERT INTO public.organisation_links VALUES ('c452f86f-cf34-4d2e-bfb0-490c56aaed1f', '7a7a33f9-3511-4b89-8648-4e73e88e73bb', '76ff7cfa-f17e-4881-ae2c-715dd69c9787', NULL, 'addresses', 'https://coral.org/', 'coral.org', 'By protecting diverse, vast, well-connected reef systems, we help corals share adaptive traits and survive a rapidly changing climate.', '2026-07-27 04:48:42.912318+00');
INSERT INTO public.organisation_links VALUES ('2f6a966c-b5d1-43ac-af82-4b079329e362', '551ab03f-7944-468b-be81-a33c61f8588e', NULL, '547bb5ce-5bea-47e4-982f-5a45e4df4f39', 'addresses', 'https://chanzuckerberg.com/blog/climate-research-initiatives/', 'chanzuckerberg.com', 'Homeworld Collective is working to build this field by cultivating a community of scientists to engage with critical problems, collate knowledge to help focus scientific efforts on the highest-impact items, and catalyze action by providing accessible funding for early-stage climate biotechnology solutions.', '2026-07-27 04:40:11.695331+00');
INSERT INTO public.organisation_links VALUES ('dae2ed29-a95f-486f-af8b-5d4012c73988', 'd20bb33a-c637-4711-82ad-985dd13760bc', NULL, '67711dda-aa0c-4061-9e3c-59425cb8b63e', 'addresses', 'https://www.decadeonrestoration.org/ocean-science-action-innovating-protect-and-restore-coral-reefs', 'decadeonrestoration.org', 'With its project 3D Purpose Built Reefs for Marine Restoration (Coast3D Reefs), Coastruction is perfecting this approach by creating a symbiosis between nature and technology.', '2026-07-27 04:40:44.189013+00');
INSERT INTO public.organisation_links VALUES ('3c8f93a3-b5b9-4a65-9197-805420797711', 'e9520c2f-f34e-43bd-b2c9-d8abe64a7fc3', NULL, '67711dda-aa0c-4061-9e3c-59425cb8b63e', 'addresses', 'https://www.decadeonrestoration.org/ocean-science-action-innovating-protect-and-restore-coral-reefs', 'decadeonrestoration.org', 'Reef Recovery 2030 – led by the Great Barrier Reef Foundation, an institutional member of the Ocean Decade Alliance – aims not only to restore the reef but also to build a global blueprint for coral reef conservation.', '2026-07-27 04:40:50.0129+00');
INSERT INTO public.organisation_links VALUES ('fae672b5-553e-47d0-a40c-21413841207e', '3970f907-fc30-42fb-bcec-85b72acd71b6', NULL, 'ba77a458-557e-4199-8b2f-fd8dfba0aaa7', 'addresses', 'https://rare.org/best-coral-reef-conservation-charities/', 'rare.org', 'Rare’s sustainable fisheries work provides a scalable model for community-led and co-managed fisheries. The program promotes sustainable fishing practices, helps rebuild fish stocks, and safeguards critical ecosystems such as coral reefs, mangroves, and seagrasses, while strengthening the livelihoods of the coastal communities who depend on them.', '2026-07-27 04:41:31.769851+00');
